      "descricao_o_que_e": "Physiocracy e a escola francesa anterior a economia politica classica britanica que organiza a economia em torno do excedente agricola, da renda da terra, da circulacao e de uma ordem natural. O DR ancora a tradicao em Quesnay (1759), *Tableau economique*, como representacao circular dos fluxos de renda e produto entre classes.\n\nTurgot (1770), *Reflections on the Formation and Distribution of Riches*, amplia a analise de riqueza, capital, juros, dinheiro e agricultura. A ficha fica como tradicao porque o DR trata a fisiocracia como dormente enquanto programa contemporaneo direto, mas importante para historia da contabilidade nacional, input-output e representacao sistemica da economia.",
