      "descricao_o_que_e": "Smithianism combina economia, filosofia moral, historia conjectural e teoria institucional em torno de divisao do trabalho, extensao do mercado, precos naturais, simpatia, ordem espontanea, Estado e critica ao mercantilismo. O DR ancora a linha em Smith (1759), *The Theory of Moral Sentiments*, e Smith (1776), *An Inquiry into the Nature and Causes of the Wealth of Nations*.\n\nO DR destaca que o tricentenario de Smith reativou debates sobre moralidade, instituicoes, dinheiro, desigualdade, confianca e capitalismo, com Ghosal, Muscatelli e Roy (2023) como porta recente de entrada. A ficha fica como linha porque a tradicao smithiana e ativa, mas opera hoje como fio interpretativo dentro de historia do pensamento, behavioral economics, NIE, public choice e capabilities.",
