      "descricao_o_que_e": "Ricardianism organiza a economia em torno de distribuicao, renda da terra, lucros, salarios, comercio e crescimento, tratando a distribuicao do excedente como problema central e nao secundario. O DR ancora a linha em Ricardo (1817), *On the Principles of Political Economy and Taxation*, e no ensaio de Ricardo (1815) sobre preco do milho, lucros e renda.\n\nA tradicao segue ativa em historia do pensamento, distribuicao, comercio, renda, rentismo e economia politica heterodoxa, com Thomas (2023), \"Ricardo and Classical Political Economy\", como sintese recente. A ficha fica como linha porque o DR a trata como subtradicao classica com forte ponte para comercio internacional, Sraffa, Marx e debates sobre conflito distributivo.",
