      "descricao_o_que_e": "Millianism e a linha tardia da economia politica classica que preserva elementos ricardianos, mas abre espaco para metodo, liberalismo, reforma social, cooperativismo, genero, educacao, liberdade individual e estado estacionario. O DR ancora a linha em Mill (1848), *Principles of Political Economy with Some of their Applications to Social Philosophy*, e em Mill (1836), \"On the Definition of Political Economy\".\n\nBackhouse e Tribe (2023) aparecem como sintese recente da vertente milliana, enquanto Bee e Desmarais-Tremblay (2023) conectam Mill ao debate sobre o nascimento do homo economicus. A ficha fica como linha porque o DR descreve o millianismo como fronteira renovada em metodo, genero, cooperativismo e estado estacionario, mas com menor massa critica que as tradicoes smithiana, marxiana e sraffiana.",
