      "confianca_ficha": "media",
      "status_ficha": "seed_externo",
      "descricao_o_que_e": "Political Marxism and Transition to Capitalism explica a emergencia do capitalismo por relacoes de propriedade, conflito de classes e formas politicas concretas, em vez de tratar comercio ou urbanizacao como causas suficientes. O DR ancora a linha em Brenner (1976), \"Agrarian Class Structure and Economic Development in Pre-Industrial Europe\", e no debate posterior sobre as raizes agrarias do capitalismo europeu.\n\nDobb (1946), *Studies in the Development of Capitalism*, Aston e Philpin (1985), *The Brenner Debate*, e Wood (2002), *The Origin of Capitalism*, organizam a agenda sobre feudalismo, capitalismo, coercao e Estado. A ficha fica como linha porque o DR a apresenta como subtradicao ativa em historia social, sociologia historica e relacoes internacionais historicas, com ponte para NIE e desenvolvimento.",
