      "status_ficha": "seed_externo",
      "descricao_o_que_e": "Analytical Marxism and Rational Choice Marxism e a linha associada ao September Group que reconstruiu teses marxistas com filosofia analitica, microfundamentos, escolha racional, teoria dos jogos e teoria da justica. O DR apresenta Cohen (1978), *Karl Marx's Theory of History: A Defence*, como uma das obras canonicas dessa reconstrucao.\n\nRoemer (1981, 1982) formaliza exploracao e classe a partir de ativos, equilibrio e escolha racional, enquanto Elster (1985), *Making Sense of Marx*, critica explicacoes funcionais e teleologicas. A dimensao formal e constitutiva e aparece no eixo Y (`ancoragem_analitica = +1.0`) e em `draws_on`, mas nao virou co-pai visual: a identidade substantiva do programa continua marxiana, e a ausencia de co-pai game-theoretic nao torna sua origem enganosa.",
