      "confianca_ficha": "media",
      "status_ficha": "seed_externo",
      "descricao_o_que_e": "Marxist Feminism and Social Reproduction Theory argumenta que o capitalismo depende da reproducao cotidiana e geracional da forca de trabalho, incluindo trabalho domestico, cuidado, saude, educacao, sexualidade, migracao, familia, raca e genero. O DR ancora a tradicao em Vogel (1983), *Marxism and the Oppression of Women*, como texto central para uma teoria unitaria da opressao e da reproducao.\n\nFraser (2016), \"Contradictions of Capital and Care\", e Bhattacharya (2017), *Social Reproduction Theory: Remapping Class, Recentering Oppression*, aparecem como referencias da fronteira contemporanea. A ficha fica como subarea porque o DR a descreve como uma das agendas mais dinamicas do marxismo atual, conectando economia feminista, welfare state, normas de genero, trabalho e desenvolvimento.",
