      "descricao_o_que_e": "Ecological Marxism and Metabolic Rift reconstroi a relacao entre capitalismo e natureza, tratando a crise ecologica como contradicao constitutiva e nao apenas externalidade corrigivel. O DR ancora a linha em Foster (2000), *Marx's Ecology: Materialism and Nature*, que torna a nocao de metabolic rift uma entrada central para reler Marx.\n\nBurkett (1999), *Marx and Nature*, Moore (2015), *Capitalism in the Web of Life*, e Saito (2017), *Karl Marx's Ecosocialism*, aparecem como obras seminais para os debates sobre metabolismo social, clima, energia, extrativismo, Antropoceno e decrescimento. A ficha fica como subarea porque o DR a apresenta como fronteira muito ativa entre marxismo, ecological economics e historia ambiental.",
