      "descricao_o_que_e": "Contemporary Historical Political Economy e o campo interdisciplinar que usa historia para estudar causas e consequencias politicas de fenomenos economicos, e causas e consequencias economicas de instituicoes politicas. O DR ancora a definicao contemporanea em Jenkins e Rubin (2023), \"Historical Political Economy: What Is It?\", texto que delimita o campo e suas fronteiras.\n\nCharnysh, Finkel e Gehlbach (2023), \"Historical Political Economy: Past, Present, and Future\", junto de Dippel e Leonard (2021) e Cirone e Spirling (2021), marca a agenda recente de causal inference, arquivos, text-as-data, GIS historico e mecanismos. A ficha fica como subarea porque o DR a descreve como muito ativa e institucionalizada, com journal e handbook proprios.",
