      "confianca_ficha": "media",
      "status_ficha": "seed_externo",
      "descricao_o_que_e": "Marginalism and the Subjective Theory of Value e o ponto de partida historico da economia neoclassica: desloca a explicacao do valor de trabalho incorporado ou custos objetivos para utilidade marginal, escassez e avaliacao subjetiva. O DR ancora a tradicao em Jevons (1871), *The Theory of Political Economy*, Menger (1871), *Principles of Economics*, e Walras (1874-1877), *Elements of Pure Economics*.\n\nComo escola independente, o marginalismo puro e hoje mais historico do que fronteira viva, mas sua linguagem foi absorvida pela microeconomia moderna. A ficha fica como tradicao porque o DR trata a revolucao marginalista como fundacao genealogica da raiz neoclassica, nao como uma aplicacao setorial.",
