      "status_ficha": "seed_externo",
      "descricao_o_que_e": "Neoclassical Welfare Economics liga equilibrio competitivo, eficiencia paretiana, excedente, compensacao hipotetica e intervencao publica. O DR ancora a subarea em Pareto (1906), *Manual of Political Economy*, Pigou (1920), *The Economics of Welfare*, Arrow (1951), *Social Choice and Individual Values*, e Arrow-Debreu (1954).\n\nA linha continua ativa, mas foi reformulada por social choice, public economics, behavioral welfare, desigualdade e desenho de politicas. A ficha fica separada de Literatura - Welfare Social Choice porque aqui o nucleo e o benchmark neoclassico de eficiencia, externalidades e avaliacao de mercados, enquanto Welfare Social Choice cobre agregacao e funcoes de bem-estar social.",
