      "descricao_o_que_e": "Neoclassical Industrial Organization and Applied Markets estuda firmas otimizadoras em mercados imperfeitos, com demanda estimada, interacao estrategica, politica antitruste e equilibrio de Nash, bayesiano ou dinamico. O DR ancora a subarea em Cournot (1838), *Recherches sur les principes mathematiques de la theorie des richesses*, Robinson (1933), Chamberlin (1933) e Tirole (1988), *The Theory of Industrial Organization*.\n\nO DR destaca que a IO moderna esta muito ativa em plataformas, dados, saude, energia, financas, mercados de informacao, inovacao e antitruste, especialmente nos *Handbook of Industrial Organization* de 2021. A ficha fica como subarea aplicada porque ela transforma o nucleo neoclassico de firmas e demanda em analise de mercados concretos e poder de mercado.",
