      "descricao_o_que_e": "Consumer and Producer Theory and Revealed Preference pergunta quais restricoes observaveis decorrem da maximizacao de utilidade ou lucro por agentes diante de orcamentos, tecnologias e precos. O DR ancora a linha em Hicks (1939), *Value and Capital*, Samuelson (1947), *Foundations of Economic Analysis*, e Afriat (1967), \"The Construction of Utility Functions from Expenditure Data\".\n\nA contribuicao central e transformar escolha individual, demanda e producao em restricoes testaveis sobre dados, inclusive quando preferencias nao sao observadas diretamente. A ficha fica como linha porque o DR a trata como base ativa de demanda, household behavior, matching, decisao sob incerteza, escolha social empirica, behavioral economics e estimacao estrutural.",
      "ancoragem_base": 1,
      "ancoragem_analitica_auto": 0.986,
