      "descricao_o_que_e": "Neoclassical Growth Theory explica crescimento de longo prazo por acumulacao de capital, crescimento populacional, preferencias e progresso tecnologico. O DR ancora a subarea em Solow (1956), \"A Contribution to the Theory of Economic Growth\", Swan (1956), \"Economic Growth and Capital Accumulation\", Cass (1965) e Koopmans (1965).\n\nO modelo Solow-Swan funciona como benchmark pedagogico, enquanto Ramsey-Cass-Koopmans introduz escolha intertemporal otima. A ficha fica como subarea porque o DR descreve a linha como ativa enquanto base de macro e desenvolvimento, com fronteiras em comercio, heterogeneidade, misallocation, tecnologia endogena, capital humano e instituicoes.",
