      "descricao_o_que_e": "Estuda como diferenças de informação e conflitos de interesse afetam trocas, contratos e alocação de recursos. Seleção adversa envolve características privadas dos participantes; sinalização e seleção por menus de contratos examinam como essa informação pode ser revelada. Risco moral trata de ações difíceis de observar ou verificar, relacionando incentivos e distribuição de risco. A teoria dos contratos também investiga direitos de decisão quando não é possível especificar ou fazer cumprir todas as contingências. Essas abordagens fundamentam aplicações em seguros, trabalho, leilões, regulação e agência política, com resultados dependentes das hipóteses de cada modelo.",
