      "descricao_o_que_e": "Neoclassical Macroeconomics, RBC, and DSGE aplica otimizacao intertemporal, equilibrio e expectativas racionais a flutuacoes macroeconomicas. O DR ancora a linha em Lucas (1972), \"Expectations and the Neutrality of Money\", Lucas (1976), \"Econometric Policy Evaluation: A Critique\", e Kydland e Prescott (1982), \"Time to Build and Aggregate Fluctuations\".\n\nKydland e Prescott (1977), \"Rules Rather than Discretion\", tambem aparece no DR como parte do giro de microfundamentos, regras e consistencia dinamica. A ficha fica como subarea porque o DR descreve RBC puro como mais benchmark do que explicacao final, mas DSGE e HANK seguem centrais na macro quantitativa com friccoes financeiras, rigidez nominal, heterogeneidade e aprendizado.",
