      "status_ficha": "seed_curso",
      "descricao_o_que_e": "Analisa como regras de votação transformam votos em resultados e como os participantes respondem a essas regras. Distingue propriedades da regra sob voto sincero de incentivos para votar estrategicamente. Black estuda a regra majoritária com preferências de pico único. Gibbard e Satterthwaite mostram limites à imunidade à manipulação: com domínio irrestrito, pelo menos três resultados possíveis e escolha determinística, uma regra não ditatorial admite manipulação em algum perfil. Isso não implica manipulação em toda eleição nem ausência de regras úteis.",
