      "confianca_ficha": "media",
      "status_ficha": "seed_externo",
      "descricao_o_que_e": "Welfare Social Choice e a subarea que pergunta como comparar estados sociais quando individuos tem preferencias, utilidades ou niveis de bem-estar diferentes. O DR ancora a linha em Bergson (1938), \"A Reformulation of Certain Aspects of Welfare Economics\", e em Harsanyi (1955), \"Cardinal Welfare, Individualistic Ethics, and Interpersonal Comparisons of Utility\", porque esses textos formalizam a funcao de bem-estar social e a admissibilidade de comparacoes interpessoais.\n\nSen (1970), \"The Impossibility of a Paretian Liberal\", e Sen (1977), \"Social Choice Theory: A Re-Examination\", deslocam a agenda para base informacional, direitos, liberdade e limites normativos do paretianismo. A ficha fica separada da raiz Social Choice Theory porque o objeto aqui nao e qualquer agregacao coletiva, mas avaliacao social de bem-estar, desigualdade, capacidades e politicas publicas.",
      "ancoragem_base": 2.1,
      "ancoragem_analitica_auto": 1.876,
      "ancoragem_analitica": 1.5
