      "confianca_ficha": "media",
      "status_ficha": "seed_externo",
      "descricao_o_que_e": "Fair Division and Fair Allocation e a subarea que pergunta como dividir recursos, bens indivisiveis, custos ou oportunidades entre agentes com preferencias distintas. Steinhaus (1948) inventa o problema matematico de fair division e Dubins-Spanier (1961) consolida a tradicao classica de cake-cutting.\n\nO marco genealogico do mapa, porem, passa a ser Foley (1967), quando envy-freeness entra na economia como problema de resource allocation e setor publico. Varian (1974), \"Equity, Envy, and Efficiency\", conecta a agenda a eficiencia de Pareto e welfare economics, enquanto Moulin (2019), \"Fair Division in the Internet Age\", marca a expansao recente para plataformas, matching, bens indivisiveis e algoritmos. A ficha fica como objeto de estudo porque o nucleo e a alocacao justa de recursos, embora use fortemente a linguagem formal de social choice e mechanism design.",
      "ancoragem_base": 2.1,
      "ancoragem_analitica_auto": 1.889,
      "ancoragem_analitica": 2
