      "status_ficha": "seed_externo",
      "descricao_o_que_e": "Computational Social Choice estuda a dimensao algoritmica da escolha coletiva: complexidade, manipulacao, controle, bribery, representacao compacta de preferencias, multiwinner voting, participatory budgeting, fair allocation e sistemas multiagente. O DR ancora a linha em Bartholdi, Tovey e Trick (1989), \"The Computational Difficulty of Manipulating an Election\", que introduz a complexidade computacional como parte do problema de manipulacao eleitoral.\n\nConitzer e Sandholm (2002) atualizam essa agenda para poucos candidatos, enquanto Brandt et al. (2016), *Handbook of Computational Social Choice*, consolida a subarea. Fish et al. (2024), \"Generative Social Choice\", aparece no DR como fronteira cautelosa em IA generativa, deliberacao e agregacao com linguagem natural.",
