      "status_ficha": "seed_curso",
      "descricao_o_que_e": "Estuda quais regras de interação podem alcançar objetivos definidos quando os participantes respondem estrategicamente e podem deter informação privada. O desenho especifica mensagens, decisões e, quando cabível, transferências, sujeito a restrições de incentivos, participação e recursos. O objetivo pode ser eficiência, receita ou outro critério explicitado pelo analista. O princípio da revelação ajuda a caracterizar resultados alcançáveis; a teoria da implementação considera também a multiplicidade de equilíbrios. Leilões, trocas bilaterais e provisão de bens públicos ilustram tanto possibilidades quanto limites: a existência de um mecanismo desejável depende das hipóteses e restrições adotadas.",
