      "confianca_ficha": "media",
      "status_ficha": "seed_externo",
      "descricao_o_que_e": "Estuda por que conflitos políticos atrasam ajustes ou sustentam políticas ineficientes. Em Alesina e Drazen, grupos esperam que os rivais aceitem uma parcela maior do custo da estabilização, gerando uma guerra de atrito. Outros modelos explicam instituições ineficientes como escolhas de grupos que se beneficiam delas. Heo e Wirsching analisam resistência burocrática que prejudica serviços e dificulta a avaliação eleitoral de reformas. Esses mecanismos não presumem que toda reforma proposta melhore o bem-estar.",
