      "confianca_ficha": "media",
      "status_ficha": "seed_externo",
      "descricao_o_que_e": "Collective Action and Logrolling é a subliteratura de Public Choice que explica como interesses coletivos conseguem ou não se organizar, como grupos pequenos com benefícios concentrados superam grupos grandes com custos difusos e como trocas legislativas podem formar coalizões de apoio a políticas. O DR ancora a linha em Buchanan e Tullock (1962), *The Calculus of Consent*, porque o livro trata regras de decisão, custos externos, custos de decisão e logrolling no estágio constitucional.\n\nOlson (1965), *The Logic of Collective Action*, é o paper/livro canônico para o problema de free riding: a contribuição central é mostrar por que interesses difusos têm dificuldade de mobilização, enquanto grupos pequenos e organizados tendem a obter influência política desproporcional. Becker (1983) estende essa intuição para competição entre grupos de pressão, conectando a linha a Special Interest Politics.",
      "ancoragem_base": 1.55,
      "ancoragem_analitica_auto": 1.409,
      "ancoragem_analitica": 1
