      "confianca_ficha": "media",
      "status_ficha": "seed_externo",
      "descricao_o_que_e": "Public Choice Theory of Bureaucracy é a linha que aplica incentivos, assimetria de informação e análise positiva ao comportamento de agências públicas, burocratas e patrocinadores políticos. O DR identifica Niskanen (1971), *Bureaucracy and Representative Government*, como a formulação clássica do bureau maximizador de orçamento, em que burocratas têm incentivos para expandir orçamento, escopo e poder organizacional.\n\nA ficha fica em escala de linha porque o DR também destaca que a versão estrita de Niskanen está historicamente dormente, embora suas perguntas sobrevivam em modelos revisionistas de agência, delegação, expertise e controle político da burocracia. Dunleavy (2019), \"The Bureaucracy as an Interest Group\", aparece como revisão recente que reavalia esse núcleo e sua substituição por formulações mais complexas.",
      "ancoragem_base": 1.55,
