      "confianca_ficha": "media",
      "status_ficha": "seed_externo",
      "descricao_o_que_e": "Expressive Voting e a linha de Public Choice que trata o voto como expressao de identidade, valores, aprovacao simbolica ou posicao moral, especialmente quando a probabilidade de um voto individual ser pivotal e baixa. Ela desloca a teoria eleitoral para alem do voto puramente instrumental e permite conectar escolha coletiva, psicologia politica e identidade.\n\nBrennan e Hamlin (1998), \"Expressive Voting and Electoral Equilibrium\", e citado no DR de Public Choice como formalizacao das implicacoes do voto expressivo para turnout e equilibrio eleitoral. O DR tambem ancora a linha em Brennan e Lomasky (1993), *Democracy and Decision*, e no survey experimental de Tyran e Wagner (2019).",
