      "status_ficha": "seed_curso",
      "descricao_o_que_e": "Investiga corrupção política, compra de votos e manipulação eleitoral, com atenção aos incentivos de partidos, intermediários e eleitores. Na vertente de máquinas políticas, Stokes modela como redes sociais e inferência sobre o voto permitem condicionar benefícios ao apoio eleitoral. A accountability perversa envolve o partido monitorar e punir o eleitor. Modelos de compromisso e credibilidade ajudam a explicar outras trocas particularistas. Sigilo do voto, informação, competição e organização territorial afetam a viabilidade desses mecanismos; corrupção, patronagem e compra de votos são conceitos relacionados, mas distintos.",
