      "confianca_ficha": "media",
      "status_ficha": "seed_externo",
      "descricao_o_que_e": "Property Rights and Measurement Costs é a subárea da New Institutional Economics que estuda como definição, alocação, mensuração e enforcement de direitos sobre recursos afetam incentivos, investimento, troca e conflito. Demsetz (1967), \"Toward a Theory of Property Rights\", é o texto canônico no DR para a tese clássica de que direitos de propriedade tendem a emergir quando os benefícios de internalizar externalidades superam os custos.\n\nBarzel (1982), \"Measurement Cost and the Organization of Markets\", desloca a linha para atributos difíceis de medir, verificar ou contratar, mostrando por que muitos problemas de propriedade são problemas de mensuração. O DR descreve a fronteira atual como mais jurídica e política, envolvendo direitos de jure e de facto, capacidade estatal, standards, propriedade intelectual, dados, plataformas e regimes híbridos.",
      "ancoragem_base": -0.25,
      "ancoragem_analitica_auto": -0.085,
      "ancoragem_analitica": 0.5
