      "status_ficha": "seed_externo",
      "descricao_o_que_e": "Investiga como conflitos de interesse, informação e dificuldade de medir contribuições individuais afetam a organização da produção. Alchian e Demsetz estudam monitoramento em equipes; Jensen e Meckling relacionam custos de agência e estrutura de propriedade. Fama e Jensen examinam como funções de decisão, controle e assunção de risco podem ser distribuídas. Esses trabalhos oferecem mecanismos distintos para analisar firmas e governança. Sua aplicação à política exige especificar quem delega, quem decide e quais instrumentos de controle estão disponíveis.",
