      "descricao_o_que_e": "Esta área investiga como regras formais, normas informais, enforcement e credibilidade moldam desempenho econômico e mudança histórica. North define instituições como restrições que estruturam interação e custos de transação; North e Weingast ligam constituições a compromisso e limites ao poder; Acemoglu, Johnson e Robinson oferecem uma estratégia empírica para relacionar instituições coloniais a diferenças de desenvolvimento. Os resultados dependem da definição de instituição, da trajetória histórica e das hipóteses de identificação, portanto não autorizam reduzir desenvolvimento a uma única variável institucional.",
