      "descricao_o_que_e": "Investiga como poder político, instituições e conflitos distributivos moldam o desenvolvimento e são transformados por ele. Abrange capacidade estatal, direitos de propriedade, clientelismo, violência e relações entre regras formais e normas sociais. Besley e Persson estudam a associação entre instituições estatais, paz e prosperidade; o volume organizado por Baland, Bourguignon, Platteau e Verdier reúne abordagens sobre mudança institucional. Bourguignon e Verdier analisam educação e democratização. A área distingue os incentivos que sustentam instituições dos efeitos que elas produzem sobre a economia.",
