      "status_ficha": "seed_externo",
      "descricao_o_que_e": "Industrial Policy and Developmental States e a subarea que compara industrializacao tardia, capacidades estatais, dependencia externa, elites empresariais, informalidade, commodities e insercao em cadeias globais. O DR ancora a linha em Gerschenkron (1962), *Economic Backwardness in Historical Perspective*, Johnson (1982), *MITI and the Japanese Miracle*, e Amsden (1989), *Asia's Next Giant*, como textos classicos sobre industrializacao tardia e Estado desenvolvimentista.\n\nEvans (1995), *Embedded Autonomy*, fornece o conceito institucional de autonomia enraizada, enquanto Bulfone (2023) marca a retomada contemporanea de politica industrial em CPE. A ficha fica sob Political Economy of Development, mas descende de Comparative Political Economy porque seu ponto e comparar capitalismos alem da OCDE e adaptar categorias para periferias, China, Africa, America Latina e Leste Europeu.",
