      "confianca_ficha": "media",
      "status_ficha": "seed_externo",
      "descricao_o_que_e": "Neo-Corporatism and Interest Intermediation e a subtradicao de Comparative Political Economy que analisa como sindicatos centralizados, associacoes empresariais e mecanismos de concertacao incorporam interesses organizados ao policymaking. O DR ancora a linha em Schmitter (1974), \"Still the Century of Corporatism?\", e em Schmitter e Lehmbruch (1979), *Trends toward Corporatist Intermediation*, como textos fundacionais sobre representacao corporatista de interesses.\n\nCameron (1978), \"The Expansion of the Public Economy\", e Katzenstein (1985), *Small States in World Markets*, conectam corporatismo a abertura economica, coordenacao domestica e capacidade de pequenos Estados responderem a choques internacionais. A ficha fica separada de Public Choice porque o foco nao e apenas grupos de interesse competindo, mas instituicoes historicas de intermediacao e concertacao.",
