      "status_ficha": "seed_externo",
      "descricao_o_que_e": "Historical Institutionalism and Institutional Change e a subtradicao de CPE que explica como instituicoes produzem trajetorias duraveis, retornos crescentes e sequenciamento historico, mas tambem mudam por layering, drift, conversion, displacement e exhaustion. O DR destaca Hall e Taylor (1996), \"Political Science and the Three New Institutionalisms\", e Pierson (2000), \"Increasing Returns, Path Dependence, and the Study of Politics\", como textos centrais da linguagem institucionalista.\n\nThelen (2004), *How Institutions Evolve*, e Streeck e Thelen (2005), *Beyond Continuity*, tornam a mudanca incremental um problema central para corrigir leituras estaticas de Varieties of Capitalism. A ficha fica separada de New Institutional Economics porque aqui o foco recai sobre sequencias historicas, coalizoes comparadas e transformacao gradual de regimes capitalistas.",
