      "status_ficha": "seed_externo",
      "descricao_o_que_e": "Varieties of Capitalism and Comparative Capitalisms e a subtradicao que compara capitalismos nacionais por seus arranjos de coordenacao entre firmas, trabalhadores, financiadores, fornecedores, treinamento e governanca corporativa. O DR ancora a linha em Hall e Soskice (2001), *Varieties of Capitalism*, que formula a distincao entre Liberal Market Economies e Coordinated Market Economies e torna complementaridades institucionais o conceito organizador.\n\nAmable (2003), *The Diversity of Modern Capitalism*, amplia a tipologia, enquanto Hall e Gingerich (2009) testam complementaridades institucionais e Schneider (2013) leva a agenda para capitalismo hierarquico na America Latina. A ficha fica como subarea porque VoC organizou grande parte da CPE depois dos anos 2000, mas hoje aparece em versao revisionista e mais geografica.",
