      "descricao_o_que_e": "Estuda transições políticas como problemas de conflito distributivo, mobilização coletiva e compromisso. Nos modelos de Acemoglu e Robinson, promessas temporárias de redistribuição podem ser insuficientes quando o poder popular é transitório. A ampliação do sufrágio pode funcionar como compromisso institucional, enquanto repressão, revolução ou reversões autoritárias permanecem alternativas em diferentes condições. Extensão do voto, consolidação democrática e revolução são processos distintos: desigualdade, custos de repressão e capacidade de mobilização alteram seus incentivos e trajetórias.",
