      "descricao_o_que_e": "Sustainability Transitions and Green Political Economy e a fronteira de CPE que explica transicoes verdes por coalizoes setoriais, poder empresarial, capacidades estatais, sistemas financeiros, relacoes industriais, politica industrial e dependencia de combustiveis fosseis. O DR ancora a linha em Bailey (2024), \"The Comparative Political Economy of Sustainability Transitions\", como entrada recente para obstaculos, aceleradores e poder em capitalismos nacionais.\n\nAllan, Lewis e Oatley (2021), \"Green Industrial Policy and the Global Transformation of Climate Politics\", conectam politica industrial verde e transformacao climatica global, enquanto Bulfone (2023) liga politica industrial a CPE. A ficha fica separada de Industrial Policy porque seu objeto central e a transicao climatica e ecologica, embora use fortemente os mecanismos de business power, growth models e capacidades estatais.",
