      "status_ficha": "seed_externo",
      "descricao_o_que_e": "Estuda a apropriação de recursos por grupos poderosos que compartilham uma base econômica e fiscal. Em Lane e Tornell, um aumento do retorno dos recursos pode provocar crescimento mais que proporcional da redistribuição, reduzindo a acumulação: o efeito voracidade. O resultado depende de condições institucionais e de parâmetros do modelo, incluindo a substituição intertemporal. Esse mecanismo ajuda a analisar ganhos inesperados de renda, mas não esgota a literatura sobre maldição dos recursos naturais.",
