      "descricao_o_que_e": "A linha trata capacidade fiscal, jurídica e administrativa como resultado endógeno de conflitos políticos e investimentos estatais. Besley e Persson modelam a formação de capacidade para proteger direitos e arrecadar, além de relacioná-la a conflito e desenvolvimento. A capacidade não é uma variável única: mecanismos fiscais, legais e coercitivos podem evoluir de modo distinto. As previsões dependem de guerra, coalizões, incentivos de governantes e complementaridades institucionais; por isso, resultados sobre crescimento ou provisão pública exigem especificar período, Estado e medida de capacidade.",
