      "status_ficha": "seed_curso",
      "descricao_o_que_e": "Analisa a troca de benefícios particularistas por apoio político, incluindo patronagem, redes de intermediários e máquinas partidárias. Stokes estuda como inserção em redes sociais e monitoramento podem sustentar a compra de votos mesmo sob voto secreto. Robinson e Verdier explicam por que empregos públicos podem constituir transferências críveis quando promessas de renda não são: as rendas associadas ao emprego vinculam o beneficiário à continuidade do governante. Os mecanismos de monitoramento, compromisso e credibilidade são distintos e não pressupõem que toda transferência seletiva seja clientelista.",
